import React, { useEffect, useId, useRef, useState } from 'react';
import { Alert, Button, Card, Checkbox, Collapse, Divider, Drawer, Empty, Form, Input, InputNumber, Modal, Popconfirm, Select, Space, Table, Tabs, Tag, Typography, message } from 'antd';
import { PlusOutlined, ReloadOutlined, SettingOutlined, DeleteOutlined } from '@ant-design/icons';

const { Text, Title, Paragraph } = Typography;
const clone = value => JSON.parse(JSON.stringify(value));

async function allRecords(api, model, filter, t) {
  const items = [];
  for (let page = 1; ; page++) {
    const result = await api.get('/api/runtime/models/' + model + '/list', { query: { page, page_size: 100, ...(filter ? { filter: JSON.stringify(filter) } : {}) } });
    items.push(...result.items);
    if (items.length >= result.total) return items;
    if (!result.items.length) throw new Error(t('Record pagination was interrupted. Refresh and try again.'));
  }
}

const LLM_TOOL_MAX = 5;
const LLM_TOOL_NAME_PATTERN = /^[A-Za-z0-9_]{1,64}$/;

function LlmToolItem({ field, providers, agents, allowReuse, onRemove, t }) {
  const form = Form.useFormInstance();
  const source = Form.useWatch(['config_json', 'llm_tools', field.name, 'source'], form);
  const providerCode = Form.useWatch(['config_json', 'llm_tools', field.name, 'provider_code'], form);
  const provider = providers.find(p => p.provider_code === providerCode);
  const reuse = allowReuse && source === 'agent';
  return <Card size="small" style={{ marginBottom: 12 }} title={t('LLM-tool {{number}}', { values: { number: field.name + 1 } })}
    extra={<Button type="link" danger onClick={onRemove}>{t('Remove')}</Button>}>
    <Form.Item label={t('Tool name')} name={[field.name, 'tool_name']} extra={t('The name used by the main model to call this submodel. Only letters, numbers, and underscores are allowed.')}
      rules={[{ required: true, whitespace: true, message: t('Please enter a tool name') }, { pattern: LLM_TOOL_NAME_PATTERN, message: t('Only letters, numbers, and underscores are allowed, up to 64 characters') }]}>
      <Input maxLength={64} placeholder={t('For example, flash_llm')} />
    </Form.Item>
    <Form.Item label={t('Tool description')} name={[field.name, 'description']} extra={t('The main model uses this description to decide when to call the submodel.')}><Input.TextArea rows={2} maxLength={300} /></Form.Item>
    {allowReuse && <Form.Item label={t('Submodel source')} name={[field.name, 'source']} initialValue="new">
      <Select options={[{ value: 'new', label: t('Create a submodel') }, { value: 'agent', label: t('Reuse an existing Agent') }]} />
    </Form.Item>}
    {reuse ? <Form.Item label={t('Reuse Agent')} name={[field.name, 'agent_id']} extra={t("Saving copies this Agent's current model and system prompt.")}
      rules={[{ required: true, message: t('Please select an Agent to reuse') }]}>
      <Select options={agents.map(a => ({ value: a.id, label: t('{{name}} ({{model}})', { values: { name: a.name || a.route_model, model: a.config_json.model_provider.model_id } }) }))} />
    </Form.Item> : <>
      <Form.Item label={t('Submodel provider')} name={[field.name, 'provider_code']} rules={[{ required: true, message: t('Please select a submodel provider') }]}>
        <Select options={providers.map(p => ({ value: p.provider_code, label: p.display_name }))}
          onChange={() => form.setFieldValue(['config_json', 'llm_tools', field.name, 'model_id'], undefined)} />
      </Form.Item>
      <Form.Item label={t('Submodel')} name={[field.name, 'model_id']} rules={[{ required: true, message: t('Please select a submodel') }]}>
        <Select showSearch optionFilterProp="label" options={(provider?.model_groups || []).map(m => ({ value: m.model_id, label: m.model_id }))} />
      </Form.Item>
      <Form.Item label={t('Submodel system prompt')} name={[field.name, 'system_prompt']}><Input.TextArea rows={3} maxLength={12000} /></Form.Item>
    </>}
  </Card>;
}

function LlmToolsField({ providers, agents, allowReuse, t }) {
  return <Form.List name={['config_json', 'llm_tools']}>
    {(fields, { add, remove }) => <>
      <Text type="secondary">{t('Attach LLM submodels as internal tools that the current Agent can call. The main model uses tool descriptions to decide when to call them.')}</Text>
      <div style={{ marginTop: 12 }}>
        {fields.map(field => <LlmToolItem key={field.key} field={field} providers={providers} agents={agents}
          allowReuse={allowReuse} t={t} onRemove={() => remove(field.name)} />)}
        <Button type="dashed" block icon={<PlusOutlined />} disabled={fields.length >= LLM_TOOL_MAX}
          onClick={() => add({ tool_name: '', description: '', source: 'new', system_prompt: '' })}>
          {fields.length >= LLM_TOOL_MAX ? t('Attach up to {{max}} LLM-tools', { values: { max: LLM_TOOL_MAX } }) : t('Add LLM-tool')}
        </Button>
      </div>
    </>}
  </Form.List>;
}

function AgentEditor({ editor, templates, providers, agents, busy, notice, onSave, onCancel, t, locale }) {
  const [form] = Form.useForm();
  const compactBaseline = useRef(null);
  const contextWindow = Form.useWatch(['config_json', 'start_model', 'context_window'], form);
  const compactPercent = Form.useWatch('compact_percent', form);
  const providerCode = Form.useWatch(['config_json', 'model_provider', 'provider_code'], form);
  const provider = providers.find(p => p.provider_code === providerCode);
  useEffect(() => {
    form.resetFields();
    const record = clone(editor.record);
    form.setFieldsValue(record);
    fillModelSettings(record.config_json?.model_provider, false);
  }, [editor]);
  function fillModelSettings(selection, replace) {
    const group = providers.find(p => p.provider_code === selection?.provider_code)?.model_groups.find(m => m.model_id === selection?.model_id);
    const current = replace ? {} : (form.getFieldValue(['config_json', 'start_model']) || {});
    const model = group?.model || {};
    const context = current.context_window ?? model.context_window;
    form.setFieldValue(['config_json', 'start_model'], {
      ...current, name: current.name || form.getFieldValue('route_model') || selection?.model_id,
      context_window: context, max_context_window: current.max_context_window ?? model.context_window,
      max_output_tokens: current.max_output_tokens ?? model.max_output_tokens,
      capabilities: { tool_call: !!model.supports_tool_call, multimodal: !!model.supports_multimodal,
        structured_output: !!model.supports_structured_output, ...current.capabilities,
        reasoning: current.capabilities?.reasoning ?? true },
      reasoning: { ...current.reasoning,
        supported_efforts: current.reasoning?.supported_efforts ?? ['low', 'medium', 'high', 'xhigh', 'max'],
        default_effort: current.reasoning?.default_effort ?? 'medium' }
    });
    const percent = current.auto_compact_token_limit && context ? Math.round(current.auto_compact_token_limit / context * 10000) / 100 : 85;
    compactBaseline.current = { context, percent, limit: current.auto_compact_token_limit };
    form.setFieldValue('compact_percent', percent);
  }
  function compactLimit(context, percent) {
    if (!Number.isSafeInteger(context) || context < 1 || !Number.isFinite(percent) || percent <= 0 || percent > 100) return undefined;
    const original = compactBaseline.current;
    // Display rounding must not rewrite an unchanged, exact token threshold.
    if (original?.context === context && original.percent === percent && original.limit != null) return original.limit;
    return Math.max(1, Math.round(context * percent / 100));
  }
  function useTemplate(id) {
    const template = templates.find(t => t.id === id);
    if (!template) return;
    const currentRoute = form.getFieldValue('route_model');
    const config = clone(template.config_json);
    config.is_default = editor.record.config_json?.is_default === true;
    form.resetFields();
    form.setFieldsValue({ name: template.name, node_template_id: template.id,
      config_json: config, route_model: currentRoute || template.config_json.model_provider.model_id });
    fillModelSettings(template.config_json.model_provider, false);
  }
  async function submit() {
    let values;
    try {
      await form.validateFields();
      // Keep the selected template's full configuration, including fields outside this form.
      values = clone(form.getFieldsValue(true));
    } catch { return; }
    const c = values.config_json;
    values.config_json = c;
    const settings = c.start_model;
    if (settings?.context_window) settings.auto_compact_token_limit = compactLimit(settings.context_window, values.compact_percent);
    delete values.compact_percent;
    const group = providers.find(p => p.provider_code === c.model_provider.provider_code)?.model_groups.find(m => m.model_id === c.model_provider.model_id);
    if (!group) return;
    c.model_metadata = { context_window: group.model.context_window, max_output_tokens: group.model.max_output_tokens,
      supports_tool_call: group.model.supports_tool_call, supports_multimodal: group.model.supports_multimodal };
    const items = c.llm_parameters?.items || {};
    // 网关不再配置温度与最大输出 Token，统一跟随模型默认值；清掉历史值避免隐藏配置继续生效。
    delete items.temperature;
    delete items.max_output_tokens;
    c.llm_parameters = { schema_version: '1.0.0', items };
    values.node_type = 'llm';
    values.name = values.name.trim();
    if (values.route_model) values.route_model = values.route_model.trim();
    await onSave(values);
  }
  const isTemplate = editor.kind === 'template';
  return <Modal title={isTemplate ? (editor.record.id ? t('Edit Agent template') : t('Create Agent template')) : t('Configure Agent')} open width={640}
    style={{ top: 24 }} styles={{ body: { maxHeight: 'calc(100dvh - 180px)', overflowY: 'auto', paddingRight: 4 } }}
    okText={isTemplate ? t('Save') : t('OK')} cancelText={t('Cancel')} onOk={submit} onCancel={onCancel} confirmLoading={busy}
    closable={!busy} maskClosable={false} cancelButtonProps={{ disabled: busy }}>
    <Form form={form} layout="vertical" disabled={busy}>
      {!isTemplate && <Form.Item label={t('Use template')} name="node_template_id" extra={t('After copying the template configuration, you can adjust the current application independently.')}>
        <Select placeholder={t('Select an Agent template')} onChange={useTemplate} options={templates.map(t => ({ value: t.id, label: t.name }))} />
      </Form.Item>}
      <Form.Item label={isTemplate ? t('Template name') : t('Agent name')} name="name" rules={[{ required: true, whitespace: true, message: t('Please enter a name') }]}>
        <Input maxLength={100} />
      </Form.Item>
      {isTemplate ? <Form.Item label={t('Template description')} name="description"><Input.TextArea rows={2} maxLength={500} /></Form.Item>
        : <Form.Item label={t('Request model name')} name="route_model" extra={t('When calling this application, enter this name in the model field.')} rules={[{ required: true, whitespace: true, message: t('Please enter a request model name') }]}><Input maxLength={120} /></Form.Item>}
      <Form.Item label={t('Model provider')} name={['config_json', 'model_provider', 'provider_code']} rules={[{ required: true, message: t('Please select a model provider') }]}>
        <Select options={providers.map(p => ({ value: p.provider_code, label: p.display_name }))} onChange={() => form.setFieldValue(['config_json', 'model_provider', 'model_id'], undefined)} />
      </Form.Item>
      <Form.Item label={t('Model')} name={['config_json', 'model_provider', 'model_id']} rules={[{ required: true, message: t('Please select a model') }, { validator: (_, value) => !value || provider?.model_groups.some(m => m.model_id === value) ? Promise.resolve() : Promise.reject(new Error(t('This model is no longer available. Please select another.'))) }]}>
        <Select showSearch optionFilterProp="label" onChange={model_id => fillModelSettings({ provider_code: providerCode, model_id }, true)} options={(provider?.model_groups || []).map(m => ({ value: m.model_id, label: m.model_id }))} />
      </Form.Item>
      <Form.Item label={t('System prompt')} name={['config_json', 'system_prompt']}><Input.TextArea rows={5} placeholder={t("Describe this Agent's responsibilities and response requirements")} maxLength={12000} showCount /></Form.Item>
      <Collapse items={[{ key: 'advanced', label: t('Advanced configuration'), forceRender: true, children: <>
      <Divider>{t('Start node model parameters')}</Divider>
      <Form.Item label={t('Model display name')} name={['config_json', 'start_model', 'name']}><Input /></Form.Item>
      <Space wrap align="start">
        <Form.Item label={t('Context window (tokens)')} name={['config_json', 'start_model', 'context_window']} dependencies={[[ 'config_json', 'start_model', 'max_context_window' ]]} rules={[{ required: true, message: t('Please enter a context window') }, { validator: (_, value) => value <= form.getFieldValue(['config_json', 'start_model', 'max_context_window']) ? Promise.resolve() : Promise.reject(new Error(t('Cannot exceed the maximum context'))) }]}><InputNumber min={1} precision={0} style={{width:220}} /></Form.Item>
        <Form.Item label={t('Maximum context (tokens)')} name={['config_json', 'start_model', 'max_context_window']} rules={[{ required:true, message:t('Please enter the maximum context') }]}><InputNumber min={1} precision={0} style={{width:220}} /></Form.Item>
        <Form.Item label={t('External maximum output tokens')} name={['config_json', 'start_model', 'max_output_tokens']} dependencies={[[ 'config_json', 'start_model', 'max_context_window' ]]} rules={[{ validator: (_, value) => value == null || value <= form.getFieldValue(['config_json', 'start_model', 'max_context_window']) ? Promise.resolve() : Promise.reject(new Error(t('Output cannot exceed the maximum context'))) }]}><InputNumber min={1} precision={0} style={{width:220}} /></Form.Item>
        <Form.Item label={t('Automatic compaction percentage (%)')} name="compact_percent" rules={[{required:true,message:t('Please enter a compaction percentage')}, {type:'number',min:0.01,max:100,message:t('Compaction percentage must be between 0.01% and 100%')}]} extra={<span>{t('Calculated from the context window; defaults to 85%.')}{compactLimit(contextWindow, compactPercent) != null && <><br /><span>{t('Compaction threshold: {{limit}} tokens', { values: { limit: compactLimit(contextWindow, compactPercent).toLocaleString(locale) } })}</span></>}</span>}><InputNumber min={0.01} max={100} precision={2} style={{width:220}} /></Form.Item>
      </Space>
      <Divider>{t('Capabilities and reasoning settings')}</Divider>
        <Space wrap>
          {[['reasoning',t('Reasoning')],['tool_call',t('Tool calling')],['multimodal',t('Multimodal')],['structured_output',t('Structured output')]].map(([key,label]) => <Form.Item key={key} name={['config_json','start_model','capabilities',key]} valuePropName="checked"><Checkbox>{label}</Checkbox></Form.Item>)}
        </Space>
        <Form.Item label={t('Supported reasoning efforts')} name={['config_json','start_model','reasoning','supported_efforts']}><Select mode="tags" options={['low','medium','high','xhigh','max'].map(value=>({value,label:{ 'low': t('Low'), 'medium': t('Medium'), 'high': t('High'), 'xhigh': t('Extra high'), 'max': t('Maximum') }[value]}))} /></Form.Item>
        <Form.Item label={t('Default reasoning effort')} name={['config_json','start_model','reasoning','default_effort']}><Select options={['low','medium','high','xhigh','max'].map(value => ({ value, label: { 'low': t('Low'), 'medium': t('Medium'), 'high': t('High'), 'xhigh': t('Extra high'), 'max': t('Maximum') }[value] }))} /></Form.Item>
      </> }, { key: 'llm-tools', label: t('LLM-tool'), forceRender: true, children: <LlmToolsField providers={providers} agents={agents} t={t} allowReuse={!isTemplate} /> }]} style={{ marginBottom: 24 }} />
    </Form>
  </Modal>;
}

function ApiKeyDialog({ ctx, gateway, onClose }) {
  const t = (key, options) => ctx.i18n.t(key, options);
  const [form] = Form.useForm();
  const [busy, setBusy] = useState(false);
  const [createdKey, setCreatedKey] = useState(null);
  const [error, setError] = useState('');
  const submitting = useRef(false);
  async function submit() {
    if (submitting.current || createdKey) return;
    submitting.current = true;
    try {
      let values;
      try { values = await form.validateFields(); } catch { return; }
      setBusy(true); setError('');
      const result = await ctx.api.post('/api/console/applications/{application_id}/api-keys', {
        path: { application_id: gateway.application_id },
        body: { name: values.name.trim(), expires_at: values.expires_at ? new Date(values.expires_at).toISOString() : null }
      });
      setCreatedKey(result);
    } catch (e) {
      setError(e);
    } finally {
      submitting.current = false; setBusy(false);
    }
  }
  return <Modal title={createdKey ? t('Key created successfully') : t('Create API Key')} open width={520}
    maskClosable={false} closable={!busy} keyboard={!busy} confirmLoading={busy}
    okText={createdKey ? t('Done') : t('Create')} cancelText={t('Cancel')}
    cancelButtonProps={{ disabled: busy, style: createdKey ? { display: 'none' } : undefined }}
    onOk={createdKey ? onClose : submit} onCancel={() => { if (!submitting.current) onClose(); }}>
    <Paragraph>{t('Application: {{name}}', { values: { name: gateway.name } })}</Paragraph>
    {createdKey ? <>
      <Alert type="success" showIcon message={t('Created successfully. Copy and save the key now. The full key is shown only once and cannot be viewed after closing.')} />
      <Paragraph style={{ marginTop: 16 }}>{createdKey.name}</Paragraph>
      <Paragraph copyable={{ text: createdKey.token }} style={{ overflowWrap: 'anywhere' }}>
        <Text code>{createdKey.token}</Text>
      </Paragraph>
    </> : <>
      {error && <Alert type="error" showIcon message={t('Creation failed: {{error}}', { values: { error: error.message } })} style={{ marginBottom: 16 }} />}
      <Form form={form} layout="vertical" disabled={busy}>
        <Form.Item label={t('Key name')} name="name" rules={[{ required: true, whitespace: true, message: t('Please enter a Key name') }]}>
          <Input autoFocus autoComplete="off" />
        </Form.Item>
        <Form.Item label={t('Expiration time')} name="expires_at" extra={t('Optional. Leave blank to never expire. Enter the time in your current device time zone.')}
          rules={[{ validator: (_, value) => !value || (Number.isFinite(new Date(value).getTime()) && new Date(value).getTime() > Date.now())
            ? Promise.resolve() : Promise.reject(new Error(t('Please select a future expiration time'))) }]}>
          <Input type="datetime-local" />
        </Form.Item>
      </Form>
    </>}
  </Modal>;
}

export default function AiGateway({ ctx }) {
  const t = (key, options) => ctx.i18n.t(key, options);
  const locale = ctx.i18n.locale.replace('_', '-');
  const [tab, setTab] = useState('apps');
  const [apps, setApps] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [templates, setTemplates] = useState([]);
  const [providers, setProviders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [stage, setStage] = useState('');
  const [notice, setNotice] = useState(null);
  const [draftView, setDraftView] = useState(null);
  const [agentEditor, setAgentEditor] = useState(null);
  const [keyGateway, setKeyGateway] = useState(null);
  const [form] = Form.useForm();
  const [messageApi, contextHolder] = message.useMessage();
  const draft = useRef(null);
  const lock = useRef(false);
  const sequence = useRef(0);
  const generation = useRef(0);

  async function refresh(nextPage = page) {
    const current = ++generation.current;
    setLoading(true);
    try {
      const [list, presetList] = await Promise.all([
        ctx.api.get('/api/runtime/models/ai_gateway/list', { query: { page: nextPage, page_size: 10, sort: 'updated_at:desc' } }),
        allRecords(ctx.api, 'node_template', undefined, t)
      ]);
      if (current !== generation.current) return;
      setApps(list.items); setTotal(list.total); setPage(nextPage); setTemplates(presetList);
    } catch (e) { if (current === generation.current) setNotice({ type: 'error', key: 'Read failed: {{error}}', values: { error: e.message } }); }
    finally { if (current === generation.current) setLoading(false); }
  }
  useEffect(() => { refresh(1); return () => { generation.current++; }; }, []);
  async function loadProviders() {
    const catalog = await ctx.api.get('/api/console/model-providers/options');
    setProviders(catalog.providers);
    return catalog.providers;
  }
  function showDraft() { setDraftView({ ...draft.current, nodes: [...draft.current.nodes] }); }
  async function openApp(gateway = null) {
    if (lock.current) return;
    lock.current = true; setLoading(true); setNotice(null);
    try {
      const [nodes] = await Promise.all([
        gateway ? allRecords(ctx.api, 'node_config', { ai_gateway_id: { $eq: gateway.id } }, t) : Promise.resolve([]),
        loadProviders()
      ]);
      draft.current = { gateway, name: gateway?.name || '', description: gateway?.description || '', nodes,
        deletedIds: [], configurationSaved: false };
      form.resetFields(); form.setFieldsValue({ name: draft.current.name, description: draft.current.description });
      if (nodes.length && !nodes.some(n => n.config_json.is_default)) nodes[0].config_json.is_default = true;
      showDraft();
    } catch (e) { setNotice({ type: 'error', key: 'Configuration read failed: {{error}}', values: { error: e.message } }); }
    finally { lock.current = false; setLoading(false); }
  }
  async function openTemplate(record = null) {
    if (lock.current) return;
    lock.current = true; setLoading(true); setNotice(null);
    try {
      await loadProviders();
      setAgentEditor({ kind: 'template', record: record ? clone(record) : { name: '', description: '', config_json: { system_prompt: '', model_provider: {}, llm_parameters: { schema_version: '1.0.0', items: {} } } } });
    } catch (e) { setNotice({ type: 'error', key: 'Model read failed: {{error}}', values: { error: e.message } }); }
    finally { lock.current = false; setLoading(false); }
  }
  function addAgent() {
    setAgentEditor({ kind: 'node', record: { id: 'local-' + Date.now().toString(36) + '-' + (++sequence.current), isNew: true,
      name: '', route_model: '', node_type: 'llm', config_json: { model_provider: {}, system_prompt: '', llm_parameters: { schema_version: '1.0.0', items: {} } } } });
  }
  async function saveAgent(values) {
    if (agentEditor.kind === 'node') {
      const old = agentEditor.record;
      if (draft.current.nodes.some(n => n.id !== old.id && n.route_model === values.route_model)) {
        setNotice({ type: 'error', key: 'Request model names are duplicated. Set a different name for each Agent.' }); return;
      }
      const next = { ...old, ...values };
      if (!draft.current.nodes.length) next.config_json.is_default = true;
      const index = draft.current.nodes.findIndex(n => n.id === old.id);
      if (index < 0) draft.current.nodes.push(next); else draft.current.nodes[index] = next;
      setAgentEditor(null); showDraft(); return;
    }
    if (lock.current) return;
    lock.current = true; setBusy(true);
    try {
      const body = { name: values.name, description: values.description || '', node_type: 'llm', config_json: values.config_json };
      if (agentEditor.record.id) await ctx.api.patch('/api/runtime/models/node_template/update/{id}', { path: { id: agentEditor.record.id }, body });
      else await ctx.api.post('/api/runtime/models/node_template/create', { body });
      setAgentEditor(null); setNotice({ type: 'success', key: 'Agent template saved. Existing application configurations remain independent.' }); await refresh();
    } catch (e) { setNotice({ type: 'error', key: 'Template save failed: {{error}}', values: { error: e.message } }); }
    finally { lock.current = false; setBusy(false); }
  }
  function removeNode(record) {
    if (!record.isNew) draft.current.deletedIds.push(record.id);
    draft.current.nodes = draft.current.nodes.filter(n => n.id !== record.id);
    if (record.config_json.is_default && draft.current.nodes.length) draft.current.nodes[0].config_json.is_default = true;
    showDraft();
  }
  async function saveApp() {
    if (lock.current) return;
    let values;
    try { values = await form.validateFields(); } catch { return; }
    if (!draft.current.nodes.length) { setNotice({ type: 'error', key: 'Please add at least one Agent first.' }); return; }
    Object.assign(draft.current, values);
    lock.current = true; setBusy(true); setNotice(null);
    try {
      await saveGateway(ctx.api, draft.current, setStage, t);
      setDraftView(null); setNotice({ type: 'success', key: 'Saved and published.' }); await refresh(1);
    } catch (e) {
      showDraft();
      setNotice({ type: 'error', key: draft.current.configurationSaved ? 'Configuration saved, but update or publication is incomplete: {{error}}' : 'Save incomplete: {{error}}', values: { error: e.message } });
    } finally { lock.current = false; setBusy(false); setStage(''); }
  }
  async function removeGateway(record) {
    if (lock.current) return;
    lock.current = true; setBusy(true);
    try {
      const nodes = await allRecords(ctx.api, 'node_config', { ai_gateway_id: { $eq: record.id } }, t);
      if (record.application_id) {
        try {
          await ctx.api.delete('/api/console/applications/{id}', { path: { id: record.application_id } });
        } catch (e) {
          // 关联应用已不存在时，继续清理网关记录及其节点配置。
          if (e.status !== 404 || e.code !== 'application') throw e;
        }
      }
      for (const node of nodes) await ctx.api.delete('/api/runtime/models/node_config/delete/{id}', { path: { id: node.id } });
      await ctx.api.delete('/api/runtime/models/ai_gateway/delete/{id}', { path: { id: record.id } });
      setNotice({ type: 'success', key: 'Gateway application and node configurations deleted.' }); await refresh(1);
    } catch (e) { setNotice({ type: 'error', key: 'Deletion incomplete: {{error}}', values: { error: e.message } }); }
    finally { lock.current = false; setBusy(false); }
  }
  async function removeTemplate(record) {
    if (lock.current) return;
    lock.current = true; setBusy(true);
    try {
      const used = await ctx.api.get('/api/runtime/models/node_config/list', { query: { page: 1, page_size: 1, filter: JSON.stringify({ node_template_id: { $eq: record.id } }) } });
      if (used.total) throw new Error(t('This template is still referenced by an application. Keep it for traceability.'));
      await ctx.api.delete('/api/runtime/models/node_template/delete/{id}', { path: { id: record.id } });
      setNotice({ type: 'success', key: 'Template deleted.' }); await refresh();
    } catch (e) { setNotice({ type: 'error', key: 'Deletion failed: {{error}}', values: { error: e.message } }); }
    finally { lock.current = false; setBusy(false); }
  }
  useEffect(() => {
    if (!notice) return;
    messageApi.open({ type: notice.type, content: t(notice.key, { values: notice.values }), duration: notice.type === 'error' ? 5 : 3 });
    setNotice(null);
  }, [notice, messageApi, t]);
  const nodeColumns = [
    { title: t('Agent'), dataIndex: 'name', width: 150 },
    { title: t('Default route'), width: 120, render: (_, n) => n.config_json.is_default ? <Tag color="green">{t('Default Agent')}</Tag> : <Button type="link" disabled={busy} onClick={() => { draft.current.nodes.forEach(item => { item.config_json.is_default = item.id === n.id; }); showDraft(); }}>{t('Set as default')}</Button> },
    { title: t('Request model name'), dataIndex: 'route_model', width: 180 },
    { title: t('Model in use'), render: (_, n) => n.config_json.model_provider.model_id, width: 180 },
    { title: t('Actions'), width: 120, render: (_, n) => <Space size={0}><Button type="link" disabled={busy} onClick={() => setAgentEditor({ kind: 'node', record: clone(n) })}>{t('Edit')}</Button><Button type="link" danger disabled={busy} onClick={() => removeNode(n)}>{t('Remove')}</Button></Space> }
  ];
  return <>{contextHolder}<div style={{ padding: 24, minWidth: 0 }}>
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 16, flexWrap: 'wrap', marginBottom: 16 }}>
      <div><Title level={4} style={{ margin: '0 0 6px' }}>{t('AI gateway applications')}</Title><Text type="secondary">{t('Configure applications with Agent templates. Saving automatically publishes them.')}</Text></div>
      <Space wrap><Button icon={<ReloadOutlined />} onClick={() => refresh()} loading={loading} disabled={busy}>{t('Refresh')}</Button>
        <Button type="primary" icon={<PlusOutlined />} disabled={loading || busy} onClick={() => tab === 'apps' ? openApp() : openTemplate()}>{tab === 'apps' ? t('Create application') : t('Create template')}</Button></Space>
    </div>
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'apps', label: t('Applications') }, { key: 'templates', label: t('Agent templates') }]} />
    {tab === 'apps' ? <Table aria-label={t('AI gateway applications')} rowKey="id" dataSource={apps} loading={loading} tableLayout="fixed" scroll={{ x: 850 }}
      pagination={{ current: page, pageSize: 10, total, showSizeChanger: false, onChange: refresh }}
      locale={{ emptyText: <Empty description={t('Create an application and select an Agent template to save and publish.')} /> }} columns={[
        { title: t('Application name'), dataIndex: 'name', width: 210, render: (name, record) => <Button type="link" style={{ padding: 0, whiteSpace: 'normal', textAlign: 'left', height: 'auto' }} onClick={() => openApp(record)} disabled={busy}>{name}</Button> },
        { title: t('Application description'), dataIndex: 'description', ellipsis: true, render: value => value || t('No description') },
        { title: t('Application association'), width: 110, render: (_, record) => <Tag>{record.application_id ? t('Associated') : t('Not associated')}</Tag> },
        { title: t('Actions'), width: 380, fixed: 'right', render: (_, record) => <Space size={0} wrap style={{ width: '100%' }}>
          <Button type="link" onClick={() => openApp(record)} disabled={busy}>{t('Configure')}</Button>
          <Button type="link" disabled={busy || !record.application_id} href={record.application_id ? '/applications/' + record.application_id + '/orchestration' : undefined}>{t('Workflow')}</Button>
          <Button type="link" disabled={busy || !record.application_id} href={record.application_id ? '/applications/' + record.application_id + '/logs' : undefined}>{t('Logs')}</Button>
          {record.application_id && <Button type="link" disabled={busy} onClick={() => setKeyGateway(record)}>{t('key')}</Button>}
          <Popconfirm title={t('Delete this gateway application?')} description={t('The associated application, published API, and node configurations will all be deleted. This cannot be undone.')} onConfirm={() => removeGateway(record)} okText={t('Delete')} cancelText={t('Cancel')}><Button type="text" danger aria-label={t('Delete gateway application')} icon={<DeleteOutlined />} disabled={busy} /></Popconfirm>
        </Space> }
      ]} /> : <Table aria-label={t('Agent templates')} rowKey="id" dataSource={templates} loading={loading} scroll={{ x: 680 }} pagination={{ pageSize: 10, showSizeChanger: false }}
      columns={[
        { title: t('Template name'), dataIndex: 'name', width: 200 }, { title: t('Description'), dataIndex: 'description', ellipsis: true },
        { title: t('Model'), width: 190, render: (_, record) => record.config_json.model_provider.model_id },
        { title: t('Actions'), width: 140, render: (_, record) => <Space size={0}><Button type="link" onClick={() => openTemplate(record)} disabled={busy}>{t('Edit')}</Button><Popconfirm title={t('Delete this template?')} onConfirm={() => removeTemplate(record)} okText={t('Delete')} cancelText={t('Cancel')}><Button type="link" danger disabled={busy}>{t('Delete')}</Button></Popconfirm></Space> }
      ]} />}
    {draftView && <ResizableDrawer title={draftView.gateway ? t('Configure application') : t('Create application')} open defaultWidth={800} resizeLabel={t('Resize drawer')} closable={!busy} maskClosable={!busy}
      onClose={() => { if (!busy) { setDraftView(null); draft.current = null; } }}
      footer={<div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}><Text type="secondary">{stage ? t(stage) : t('Saving automatically updates the orchestration and publishes it')}</Text><Space><Button disabled={busy} onClick={() => { setDraftView(null); draft.current = null; }}>{t('Cancel')}</Button><Button type="primary" onClick={saveApp} loading={busy}>{t('Save')}</Button></Space></div>}>
      <Form form={form} layout="vertical" disabled={busy}>
        <Form.Item label={t('Application name')} name="name" rules={[{ required: true, whitespace: true, message: t('Please enter an application name') }]}><Input maxLength={100} /></Form.Item>
        <Form.Item label={t('Application description')} name="description"><Input.TextArea rows={2} maxLength={1000} /></Form.Item>
      </Form>
      <Divider />
      <Text type="secondary">{t('The default Agent is used when model is omitted. Unknown models still return an error.')}</Text>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}><Text strong>{t('Agent configuration')}</Text><Button icon={<PlusOutlined />} onClick={addAgent} disabled={busy || draftView.nodes.length >= 50}>{t('Add Agent')}</Button></div>
      <Table rowKey="id" dataSource={draftView.nodes} columns={nodeColumns} size="small" pagination={false} scroll={{ x: 630 }} locale={{ emptyText: <Empty description={t('Add an Agent, select a template, and set its request model name.')} /> }} />
    </ResizableDrawer>}
    {keyGateway && <ApiKeyDialog ctx={ctx} gateway={keyGateway} onClose={() => setKeyGateway(null)} />}
    {agentEditor && <AgentEditor editor={agentEditor} templates={templates} providers={providers}
      agents={(draft.current?.nodes || []).filter(n => n.id !== agentEditor.record.id)}
      t={t} locale={locale} busy={busy} notice={null} onSave={saveAgent} onCancel={() => { if (!busy) setAgentEditor(null); }} />}
  </div></>;
}

async function saveGateway(api, draft, onStage, t) {
  if (!draft.nodes.length) throw new Error(t('Configure at least one Agent'));
  if (draft.uncertainCreate) throw new Error(t('The previous creation result is not confirmed. Refresh the list and verify it before continuing to avoid duplicates.'));
  const applicationPath = '/api/console/applications/{id}';
  const orchestrationPath = applicationPath + '/orchestration';
  let state = null;
  if (draft.gateway?.application_id) {
    state = await api.get(orchestrationPath, { path: { id: draft.gateway.application_id } });
  }
  onStage('Saving configuration');
  const values = { name: draft.name.trim(), description: draft.description || '' };
  if (!draft.gateway) {
    draft.uncertainCreate = true;
    draft.gateway = await api.post('/api/runtime/models/ai_gateway/create', { body: values });
    draft.uncertainCreate = false;
  } else {
    const updated = await api.patch('/api/runtime/models/ai_gateway/update/{id}', { path: { id: draft.gateway.id }, body: values });
    draft.gateway = { ...draft.gateway, ...updated };
  }
  if (!draft.gateway.application_id) {
    if (!draft.pendingApplication) {
      draft.uncertainCreate = true;
      draft.pendingApplication = await api.post('/api/console/applications', {
        body: { application_type: 'agent_flow', name: values.name, description: values.description, icon: null, icon_type: null, icon_background: null }
      });
      draft.uncertainCreate = false;
    }
    draft.gateway = await api.patch('/api/runtime/models/ai_gateway/update/{id}', {
      path: { id: draft.gateway.id }, body: { application_id: draft.pendingApplication.id }
    });
  }
  const application_id = draft.gateway.application_id;
  if (!state) state = await api.get(orchestrationPath, { path: { id: application_id } });
  for (const item of draft.nodes) {
    const body = { ai_gateway_id: draft.gateway.id, name: item.name, node_type: item.node_type,
      route_model: item.route_model, config_json: item.config_json };
    if (item.node_template_id) body.node_template_id = item.node_template_id;
    if (item.isNew) {
      draft.uncertainCreate = true;
      const saved = await api.post('/api/runtime/models/node_config/create', { body });
      Object.assign(item, saved, { isNew: false });
      draft.uncertainCreate = false;
    } else {
      await api.patch('/api/runtime/models/node_config/update/{id}', { path: { id: item.id }, body });
    }
  }
  while (draft.deletedIds.length) {
    await api.delete('/api/runtime/models/node_config/delete/{id}', { path: { id: draft.deletedIds[0] } });
    draft.deletedIds.shift();
  }
  draft.configurationSaved = true;
  onStage('Generating orchestration');
  const document = buildGatewayDocument({ flow_id: state.flow_id, ...values, nodes: draft.nodes }, t);
  onStage('Saving orchestration');
  await api.put(orchestrationPath + '/draft', { path: { id: application_id }, body: {
    document, change_kind: 'logical', summary: '保存 AI 网关固定模板配置'
  } });
  onStage('Publishing');
  const publication = await api.post('/api/console/applications/{application_id}/api-publications', { path: { application_id }, body: {
    api_enabled: true, mapping: { input: { query_target: 'node-start.query', model_target: 'node-start.model',
      history_target: 'node-start.history', attachments_target: 'node-start.attachments', inputs_target: 'node-start.inputs' },
      output: { answer_selector: 'node-answer.answer' } }
  } });
  if (!publication.active || !publication.api_enabled) throw new Error(t('The server has not confirmed that publication is active. Check the application publication status.'));
  return publication;
}


// This fixed-template page owns the generated graph; current configuration replaces the previous draft.
function buildGatewayDocument(input, t) {
  const { flow_id, name, description = '', nodes } = input;
  if (!flow_id || !name || !name.trim()) throw new Error(t('Please enter an application name and flow identifier'));
  if (!Array.isArray(nodes) || !nodes.length) throw new Error(t('Configure at least one LLM node'));
  if (nodes.length > 50) throw new Error(t('A gateway can have up to 50 LLM nodes'));
  const defaults = nodes.filter(n => n.config_json?.is_default);
  if (defaults.length > 1) throw new Error(t('Only one default Agent can be specified'));
  const defaultId = defaults[0]?.id || nodes[0].id;
  const routes = new Set(), ids = new Set();
  for (const item of nodes) {
    if (item.node_type !== 'llm') throw new Error(t('The current fixed template only accepts LLM nodes'));
    if (!item.id || ids.has(item.id)) throw new Error(t('Node identifiers are missing or duplicated'));
    ids.add(item.id);
    if (!item.route_model || item.route_model !== item.route_model.trim()) throw new Error(t('Please enter a valid request model name'));
    if (routes.has(item.route_model)) throw new Error(t('Duplicate request model name: {{model}}', { values: { model: item.route_model } }));
    routes.add(item.route_model);
    const c = item.config_json;
    if (!c || !c.model_provider || !c.model_provider.provider_code || !c.model_provider.model_id) throw new Error(t('Please select a model for the node'));
    if (c.system_prompt !== undefined && typeof c.system_prompt !== 'string') throw new Error(t('The system prompt must be text'));
  }
  // LLM-tool 子模型：挂载项始终生成独立子节点；复用已有 Agent 时按当前配置复制模型与提示词。
  const llmToolsByNode = new Map(), llmToolNames = new Set();
  for (const item of nodes) {
    const tools = Array.isArray(item.config_json.llm_tools) ? item.config_json.llm_tools : [];
    if (tools.length > LLM_TOOL_MAX) throw new Error(t('An Agent can attach up to {{max}} LLM-tools', { values: { max: LLM_TOOL_MAX } }));
    if (!tools.length) continue;
    const resolved = [];
    for (const tool of tools) {
      const toolName = (tool?.tool_name || '').trim();
      if (!LLM_TOOL_NAME_PATTERN.test(toolName)) throw new Error(t('LLM-tool names can only contain letters, numbers, and underscores, up to 64 characters'));
      if (llmToolNames.has(toolName)) throw new Error(t('Duplicate LLM-tool name: {{name}}', { values: { name: toolName } }));
      llmToolNames.add(toolName);
      if (tool.source === 'agent') {
        const reused = nodes.find(n => n.id === tool.agent_id && n.id !== item.id);
        if (!reused) throw new Error(t('The Agent referenced by LLM-tool "{{name}}" does not exist', { values: { name: toolName } }));
        resolved.push({ tool_name: toolName, description: (tool.description || '').trim(),
          model_provider: JSON.parse(JSON.stringify(reused.config_json.model_provider)), system_prompt: reused.config_json.system_prompt || '' });
      } else {
        const providerCode = tool.provider_code || tool.model_provider?.provider_code;
        const modelId = tool.model_id || tool.model_provider?.model_id;
        if (!providerCode || !modelId) throw new Error(t('Please select a submodel for LLM-tool "{{name}}"', { values: { name: toolName } }));
        resolved.push({ tool_name: toolName, description: (tool.description || '').trim(),
          model_provider: { provider_code: providerCode, model_id: modelId }, system_prompt: tool.system_prompt || '' });
      }
    }
    llmToolsByNode.set(item.id, resolved);
  }
  function node(id, type, alias, x, y, config, bindings, outputs) {
    return { id, type, alias, description: '', containerId: null, position: { x, y }, configVersion: 1,
      config: config || {}, bindings: bindings || {}, outputs: outputs || [] };
  }
  function edge(id, source, target, sourceHandle) {
    return { id, source, target, sourceHandle: sourceHandle || null, targetHandle: null, containerId: null, points: [] };
  }
  const startId = 'node-start', routeId = 'node-router', aggregateId = 'node-aggregate';
  const start = node(startId, 'start', '请求输入', 80, 180, {
    input_fields: [], model_list: nodes.map(item => {
      const meta = item.config_json.model_metadata || {};
      const settings = item.config_json.start_model || {};
      const context = settings.context_window ?? meta.context_window;
      const maxContext = settings.max_context_window ?? meta.context_window;
      const output = settings.max_output_tokens ?? meta.max_output_tokens;
      const limit = settings.auto_compact_token_limit ?? (context ? Math.round(context * 0.85) : undefined);
      for (const v of [context, maxContext, output, limit]) {
        if (v != null && (!Number.isSafeInteger(v) || v <= 0)) throw new Error(t('Token parameters must be positive integers'));
      }
      if (context && maxContext && context > maxContext) throw new Error(t('Context cannot exceed the maximum context'));
      if (limit && context && limit > context) throw new Error(t('Compaction threshold cannot exceed the context'));
      if (output && maxContext && output > maxContext) throw new Error(t('Output cannot exceed the maximum context'));
      return { ...settings, id: item.route_model, name: settings.name || item.route_model,
        ...(context ? { context_window: context } : {}), ...(maxContext ? { max_context_window: maxContext } : {}),
        ...(output ? { max_output_tokens: output } : {}), ...(limit ? { auto_compact_token_limit: limit } : {}),
        capabilities: settings.capabilities || { tool_call: !!meta.supports_tool_call, multimodal: !!meta.supports_multimodal } };

    })
  });
  const branches = nodes.map((item, index) => ({
    id: index ? 'else-if-' + index : 'if', kind: index ? 'else_if' : 'if',
    sourceHandle: index ? 'else-if-' + index : 'if', title: item.route_model,
    condition: { operator: item.id === defaultId ? 'or' : 'and', conditions: [{ kind: 'rule', left: [startId, 'model'], comparator: 'equals',
      right: { kind: 'constant', value: item.route_model } }, ...(item.id === defaultId ? [{ kind: 'rule', left: [startId, 'model'], comparator: 'empty' }] : [])] }
  }));
  branches.push({ id: 'else', kind: 'else', sourceHandle: 'else', title: '未匹配模型' });
  const graphNodes = [start, node(routeId, 'if_else', '按模型分发', 340, 180, {}, {
    branches: { kind: 'if_else_branches', value: { branches } }
  })];
  const graphEdges = [edge('entry', startId, routeId)];
  const candidates = [];
  let toolRow = 0;
  nodes.forEach((item, index) => {
    const id = 'llm-' + item.id, c = item.config_json;
    const llmTools = llmToolsByNode.get(item.id) || [];
    const systemPrompt = c.system_prompt || '';
    const prompts = [
      { id: 'system', role: 'system', content: { kind: 'templated_text', value: ['{{node-start.system}}', systemPrompt].filter(Boolean).join('\n\n') } },
      { id: 'user', role: 'user', content: { kind: 'templated_text', value: '{{node-start.query}}' } }
    ];
    graphNodes.push(node(id, 'llm', item.name || item.route_model, 620, 80 + index * 180, {
      model_provider: JSON.parse(JSON.stringify(c.model_provider)), response_format: { mode: 'text' },
      context_policy: { context_selector: [startId, 'history'], integration_context: 'enabled' },
      protocol_context: { kind: 'selector', value: [startId, 'protocol_context'] },
      external_reasoning_policy: { follow_external_reasoning: true },
      retry_enabled: false, max_retries: 1, retry_interval_ms: 500,
      llm_parameters: JSON.parse(JSON.stringify(c.llm_parameters || { schema_version: '1.0.0', items: {} })),
      ...(llmTools.length ? {
        visible_internal_llm_tools_enabled: true,
        visible_internal_llm_tools: llmTools.map(tool => ({
          type: 'visible_internal_llm_tool', connector_id: tool.tool_name, tool_name: tool.tool_name,
          tool_mode: 'agent', external_tool_policy: 'inherited', internal_llm_node_policy: 'allowed',
          input_schema: { type: 'object', properties: { tasks: { type: 'string', description: 'task' } }, required: ['tasks'] },
          ...(tool.description ? { description: tool.description } : {})
        }))
      } : {})
    }, { prompt_messages: { kind: 'prompt_messages', value: prompts } }, [
      { key: 'text', title: '模型输出', valueType: 'string' }, { key: 'usage', title: '用量', valueType: 'json' }
    ]));
    candidates.push([id, 'text']);
    graphEdges.push(edge('route-' + index, routeId, id, branches[index].sourceHandle), edge('aggregate-' + index, id, aggregateId));
    llmTools.forEach((tool, toolIndex) => {
      const toolNodeId = 'llm-tool-' + tool.tool_name, resultNodeId = 'tool-result-' + tool.tool_name;
      const y = 80 + (nodes.length + 1 + toolRow) * 180;
      toolRow++;
      graphNodes.push(node(toolNodeId, 'llm', tool.tool_name, 620, y, {
        model_provider: tool.model_provider, response_format: { mode: 'text' },
        context_policy: { context_selector: [startId, 'history'], integration_context: 'enabled' },
        protocol_context: { kind: 'selector', value: [startId, 'protocol_context'] },
        external_reasoning_policy: { follow_external_reasoning: false },
        external_model_parameter_policy: { follow_external_max_output_tokens: false },
        retry_enabled: false, max_retries: 1, retry_interval_ms: 500, mcp_instance_ids: [],
        visible_internal_llm_tools_enabled: false, visible_internal_llm_tools: [],
        llm_parameters: { schema_version: '1.0.0', items: {} }
      }, { prompt_messages: { kind: 'prompt_messages', value: [
        { id: 'system', role: 'system', content: { kind: 'templated_text', value: tool.system_prompt } },
        { id: 'user', role: 'user', content: { kind: 'templated_text', value: '{{visible_internal_llm_tool.arguments.tasks}}' } }
      ] } }, [
        { key: 'text', title: '模型输出', valueType: 'string' }, { key: 'usage', title: '用量', valueType: 'json' }
      ]));
      graphNodes.push(node(resultNodeId, 'tool_result', '工具返回', 900, y, {}, {
        result_template: { kind: 'templated_text', value: '{{' + toolNodeId + '.text}}' }
      }, [{ key: 'result', title: '工具返回', valueType: 'string' }]));
      graphEdges.push(edge('llm-tool-' + index + '-' + toolIndex, id, toolNodeId, 'visible_internal_llm_tool:' + tool.tool_name),
        edge('llm-tool-result-' + index + '-' + toolIndex, toolNodeId, resultNodeId, 'source-right'));
    });
  });
  graphNodes.push(node(aggregateId, 'variable_aggregator', '选取已执行分支', 900, 180, {}, {
    groups: { kind: 'variable_groups', value: [{ key: 'group1', valueType: 'string', candidates }] }
  }, [{ key: 'group1', title: 'group1', valueType: 'string' }]));
  graphNodes.push(node('node-answer', 'answer', '直接回复', 1160, 180, {}, {
    answer_template: { kind: 'templated_text', value: '{{node-aggregate.group1}}' }
  }, [{ key: 'answer', title: '回复', valueType: 'string' }]));
  graphNodes.push(node('node-unmatched', 'answer', '未匹配模型', 620, 80 + nodes.length * 180, {}, {
    answer_template: { kind: 'templated_text', value: '不支持该模型，请使用此应用已配置的请求模型名称。' }
  }, [{ key: 'answer', title: '回复', valueType: 'string' }]));
  graphEdges.push(edge('reply', aggregateId, 'node-answer'), edge('unmatched', routeId, 'node-unmatched', 'else'));
  return { schemaVersion: '1flowbase.flow/v2', meta: { flowId: flow_id, name: name.trim(), description, tags: [] },
    graph: { nodes: graphNodes, edges: graphEdges }, editor: { viewport: { x: 0, y: 0, zoom: 0.75 }, annotations: [], activeContainerPath: [] } };
}


const DEFAULT_WIDTH = 720;
const DEFAULT_MIN_WIDTH = 480;
const DEFAULT_MAX_WIDTH = 1200;
const NATIVE_DRAGGER_HIT_WIDTH = 16;
const NATIVE_DRAGGER_OFFSET = -NATIVE_DRAGGER_HIT_WIDTH / 2;
const WIDTH_STORAGE_KEY_PREFIX = 'resizable-drawer:width:';
function ResizableDrawer({ closable = true, maskClosable = false, ariaLabel, bodyClassName, children, defaultWidth = DEFAULT_WIDTH, destroyOnClose, extra, footer, maxWidth = DEFAULT_MAX_WIDTH, minWidth = DEFAULT_MIN_WIDTH, onClose, open, resizeLabel, rootClassName, title, viewportGutter = 0, zIndex }) {
    const titleId = useId();
    const storageKey = pageWidthStorageKey();
